# A helper function that creates a figure from code
save_png <- function(code, width = 1000, height = 1000) {
  path <- tempfile(fileext = ".png")
  on.exit(unlink(path), add = TRUE)
  png(path, width = width, height = height)
  code
  dev.off()
}

